parameters.jsCode:
const state = String($json.state || 'missing');
const opportunityId = $json.opportunity_id == null ? 'missing' : String($json.opportunity_id);
if (!['guard_delivery_pending', 'unassigned_alerted'].includes(state)) {
  throw new Error(`unexpected_routing_transition_state state=${state} opportunity_id=${opportunityId}`);
}
return [{ json: $json }];

